import{_ as i,a0 as s,w as a,s as d,I as e,x as o,a1 as p,A as r,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Conky - 終極的 X 視窗系統監視器應用 | LCTT x X-CMD","titleTemplate":false,"description":"Conky - 終極的 X 視窗系統監視器應用 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Conky - 終極的 X 視窗系統監視器應用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Conky - 終極的 X 視窗系統監視器應用 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150331 Conky--The Ultimate X Based System Monitor Application","title":"Conky - 終極的 X 視窗系統監視器應用","tag":"201505","desc":""},"relativePath":"201505/20150331 Conky--The Ultimate X Based System Monitor Application.md","filePath":"[post].md"}'),u={name:"201505/20150331 Conky--The Ultimate X Based System Monitor Application.md"};function y(k,t,m,c,C,f){const n=s("Link");return a(),d("div",null,[t[26]||(t[26]=e("h1",{id:"conky-終極的-x-視窗系統監視器應用",tabindex:"-1"},[o("Conky - 終極的 X 視窗系統監視器應用 "),e("a",{class:"header-anchor",href:"#conky-終極的-x-視窗系統監視器應用","aria-label":"Permalink to “Conky - 終極的 X 視窗系統監視器應用”"},"​")],-1)),e("p",null,[t[1]||(t[1]=o("Conky 是一個用 ‘C’ 語言寫就的系統監視器，並在 GNU GPL 和 BSD 許可協議下發布，在 Linux 和 BSD 操作系統中都可以獲取到它。這個應用是基於 X 視窗系統的，原本由 ",-1)),p(n,{href:"http://torsmo.sourceforge.net/"},{default:r(()=>[...t[0]||(t[0]=[o("Torsmo",-1)])]),_:1}),t[2]||(t[2]=o(" 分支而來。",-1))]),t[27]||(t[27]=l(`<h4 id="特點" tabindex="-1">特點 <a class="header-anchor" href="#特點" aria-label="Permalink to “特點”">​</a></h4><ul><li>簡潔的用户界面;</li><li>高度可配置;</li><li>它既可使用內置的部件(超過 300 多個) 也可使用外部腳本，來在桌面或其自有容器中展示系統的狀態；</li><li>低資源消耗;</li><li>它可顯示範圍廣泛的系統參數，包括但不限於 CPU，內存，swap 分區 ，温度，進程，磁盤使用情況，網絡狀態，電池電量，郵件收發，系統消息，音樂播放器的控制，天氣信息，最新新聞，升級信息等等；</li><li>在許多操作系統中如 CrunchBang Linux 和 Pinguy OS 被默認安裝；</li></ul><h4 id="關於-conky-的少有人知的事實" tabindex="-1">關於 Conky 的少有人知的事實 <a class="header-anchor" href="#關於-conky-的少有人知的事實" aria-label="Permalink to “關於 Conky 的少有人知的事實”">​</a></h4><ul><li>conky 這個名稱來自於一個加拿大電視節目；</li><li>它已被移植到 Nokia N900 上；</li><li>官方已經不再維護它了；</li></ul><h3 id="在-linux-中-conky-的安裝和使用" tabindex="-1">在 Linux 中 Conky 的安裝和使用 <a class="header-anchor" href="#在-linux-中-conky-的安裝和使用" aria-label="Permalink to “在 Linux 中 Conky 的安裝和使用”">​</a></h3><p>在我們安裝 conky 之前，我們需要使用下面的命令來安裝諸如 <code>lm-sensors</code>, <code>curl</code> 和 <code>hddtemp</code> 之類的軟件包：</p><pre><code># apt-get install lm-sensors curl hddtemp
</code></pre><p>然後是檢測傳感器：</p><pre><code># sensors-detect
</code></pre><p><strong>注</strong>: 在被系統提示時，回答 ‘Yes’ 。</p><p>檢測所有探測到的傳感器：</p><pre><code># sensors
</code></pre><h4 id="樣例輸出" tabindex="-1">樣例輸出 <a class="header-anchor" href="#樣例輸出" aria-label="Permalink to “樣例輸出”">​</a></h4><pre><code>acpitz-virtual-0
Adapter: Virtual device
temp1:        +49.5°C  (crit = +99.0°C)

coretemp-isa-0000
Adapter: ISA adapter
Physical id 0:  +49.0°C  (high = +100.0°C, crit = +100.0°C)
Core 0:         +49.0°C  (high = +100.0°C, crit = +100.0°C)
Core 1:         +49.0°C  (high = +100.0°C, crit = +100.0°C)
</code></pre><p>Conky 既可以從軟件倉庫中安裝，也可從源代碼編譯得到：</p><pre><code># yum install conky              [在 RedHat 系的系統上]
# apt-get install conky-all      [在 Debian 系的系統上]
</code></pre>`,16)),e("p",null,[t[4]||(t[4]=e("strong",null,"注",-1)),t[5]||(t[5]=o(": 在 Fedora/CentOS 上安裝 conky 之前，你必須啓用 ",-1)),p(n,{href:"https://linux.cn/article-2324-1.html"},{default:r(()=>[...t[3]||(t[3]=[o("EPEL 軟件倉庫",-1)])]),_:1}),t[6]||(t[6]=o("。",-1))]),t[28]||(t[28]=l(`<p>在安裝完 conky 之後，只需輸入如下命令來開啓它：</p><pre><code>$ conky &amp;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Start-Conkey.jpeg" alt="正在運行的 Conky 監視器"></p><p><em>正在運行的 Conky 監視器</em></p><p>這使得 conky 以一個彈窗的形式運行，並使用位於 <code>/etc/conky/conky.conf</code> 的 conky 基本配置文件。</p><p>你可能想將 conky 集成到桌面上，並不想讓它每次以彈窗的形式出現，下面就是你需要做的：</p><p>將配置文件 <code>/etc/conky/conky.conf</code> 複製到你的家目錄中，並將它重命名為 <code>.conkyrc</code>，開頭的點號 (.) 是為了確保這個配置文件是隱藏的。</p><pre><code>$ cp /etc/conky/conky.conf /home/$USER/.conkyrc
</code></pre><p>現在重啓 conky 來應用新的更改：</p><pre><code>$ killall -SIGUSR1 conky
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Restart-Conky.jpeg" alt="Conky 監視器窗口"></p><p><em>Conky 監視器窗口</em></p><p>你可能想編輯位於你的家目錄的 conky 的配置文件，這個配置文件的內容是非常容易理解的。</p><p>下面是 conky 配置文件的一個樣例：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Conky-Configuration.jpeg" alt="Conky 的配置"></p><p><em>Conky 的配置</em></p><p>從上面的窗口中，你可以更改顏色，邊框，大小，縮放比例，背景，對齊方式及幾個其他屬性。通過為不同的 conky 窗口設定不同的對齊方式，我們可以同時運行幾個 conky 腳本。</p><p><strong>讓 conky 使用其它腳本而不是默認配置，以及如何找到這些腳本？</strong></p><p>你可以編寫你自己的 conky 腳本或使用來自於互聯網的腳本；我們並不建議你使用從互聯網中找到的具有潛在危險的任何腳本，除非你清楚你正在做什麼。然而，有一些著名的主題和網頁包含可信賴的 conky 腳本，例如下面所提及的：</p>`,19)),e("ul",null,[e("li",null,[p(n,{href:"http://ubuntuforums.org/showthread.php?t=281865"},{default:r(()=>[...t[7]||(t[7]=[o("http://ubuntuforums.org/showthread.php?t=281865",-1)])]),_:1})]),e("li",null,[p(n,{href:"http://conky.sourceforge.net/screenshots.html"},{default:r(()=>[...t[8]||(t[8]=[o("http://conky.sourceforge.net/screenshots.html",-1)])]),_:1})])]),t[29]||(t[29]=l(`<p>在上面的 URL 地址中，你將發現其中每個截圖都有一個超鏈接，它們將指向到腳本文件。</p><h4 id="測試-conky-腳本" tabindex="-1">測試 Conky 腳本 <a class="header-anchor" href="#測試-conky-腳本" aria-label="Permalink to “測試 Conky 腳本”">​</a></h4><p>這裏我將在我的 Debian Jessie 系統中運行一個由第三方寫的 conky 腳本，以此來進行測試：</p><pre><code>$ wget https://github.com/alexbel/conky/archive/master.zip
$ unzip master.zip 
</code></pre><p>切換當前工作目錄到剛才解壓的目錄：</p><pre><code>$ cd conky-master
</code></pre><p>將 <code>secrets.yml.example</code> 重命名為 <code>secrets.yml</code>：</p><pre><code>$ mv secrets.yml.example secrets.yml
</code></pre><p>在你需要運行這個(ruby)腳本之前安裝 Ruby：</p><pre><code>$ sudo apt-get install ruby
$ ruby starter.rb 
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Conky-Fancy-Look.jpeg" alt="華麗的 conky 外觀"></p><p><em>華麗的 conky 外觀</em></p><p><strong>注</strong>: 可以修改這個腳本以展示你當前的天氣，温度等；</p><p>假如你想讓 conky 開機自啓，請在開機啓動應用設置(startup Applications) 中添加如下的幾行命令：</p><pre><code>conky --pause 10 
save and exit.
</code></pre>`,15)),e("p",null,[t[10]||(t[10]=o("最後，如此輕量級且吸引眼球的實用 GUI 軟件包不再處於活躍狀態且官方不再進行維護了。最新的穩定發佈版本為 conky 1.9.0， 於 2012 年 5 月 3 號發佈。在 Ubuntu 論壇上，一個有關用户分享 conky 配置的主題已經超過了 2000 多頁。(這個論壇主題的鏈接為: ",-1)),p(n,{href:"http://ubuntuforums.org/showthread.php?t=281865/"},{default:r(()=>[...t[9]||(t[9]=[o("http://ubuntuforums.org/showthread.php?t=281865/",-1)])]),_:1}),t[11]||(t[11]=o(")",-1))]),e("ul",null,[e("li",null,[p(n,{href:"http://conky.sourceforge.net/"},{default:r(()=>[...t[12]||(t[12]=[o("Conky 主頁",-1)])]),_:1})])]),t[30]||(t[30]=e("p",null,"這就是全部內容了。保持聯繫，保持評論。請在下面的評論框裏分享你的想法和配置。",-1)),t[31]||(t[31]=e("hr",null,null,-1)),e("p",null,[t[14]||(t[14]=o("via: ",-1)),p(n,{href:"http://www.tecmint.com/install-conky-in-ubuntu-debian-fedora/"},{default:r(()=>[...t[13]||(t[13]=[o("http://www.tecmint.com/install-conky-in-ubuntu-debian-fedora/",-1)])]),_:1})]),e("p",null,[t[18]||(t[18]=o("作者：",-1)),p(n,{href:"http://www.tecmint.com/author/avishek/"},{default:r(()=>[...t[15]||(t[15]=[o("Avishek Kumar",-1)])]),_:1}),t[19]||(t[19]=o(" 譯者：",-1)),p(n,{href:"https://github.com/FSSlc"},{default:r(()=>[...t[16]||(t[16]=[o("FSSlc",-1)])]),_:1}),t[20]||(t[20]=o(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[17]||(t[17]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[23]||(t[23]=o("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[21]||(t[21]=[o("LCTT",-1)])]),_:1}),t[24]||(t[24]=o(" 原創翻譯，",-1)),p(n,{href:"http://linux.cn/"},{default:r(()=>[...t[22]||(t[22]=[o("Linux中國",-1)])]),_:1}),t[25]||(t[25]=o(" 榮譽推出",-1))])])}const w=i(u,[["render",y]]);export{T as __pageData,w as default};
